import { test } from 'node:test';
import assert from 'node:assert/strict';
import { median } from './stats.js';

test('median of even-length array is the mean of the two middle values', () => {
  assert.equal(median([1, 2, 3, 4]), 2.5);
});

test('median of two-element array', () => {
  assert.equal(median([1, 2]), 1.5);
});

test('median of even-length unsorted array sorts first', () => {
  assert.equal(median([4, 1, 3, 2]), 2.5);
});

test('median of odd-length array is the middle value', () => {
  assert.equal(median([1, 2, 3]), 2);
  assert.equal(median([3, 1, 2]), 2);
});

test('median does not mutate its input', () => {
  const input = [3, 1, 2];
  median(input);
  assert.deepEqual(input, [3, 1, 2]);
});

